#!/bin/bash
# ═══════════════════════════════════════════════════════
# render-build.sh — Runs on Render before serving the app
# Generates config.js from Render Environment Variables
# ═══════════════════════════════════════════════════════
echo "🔧 Generating config.js from environment variables..."

cat > config.js << EOF
/* Auto-generated by render-build.sh — do not edit manually */
const APP_CONFIG = {
  firebase: {
    apiKey:      "${FIREBASE_API_KEY}",
    authDomain:  "${FIREBASE_AUTH_DOMAIN}",
    projectId:   "${FIREBASE_PROJECT_ID}",
    databaseURL: "${FIREBASE_DATABASE_URL}",
  },
  geminiApiKey:        "${GEMINI_API_KEY}",
  defaultDeviceId:     "esp32-desk-01",
  appName:             "StudyAI Companion",
  maxSessionHistory:   50,
  sessionTargetMinutes: 120,
};
EOF

echo "✅ config.js generated successfully!"
cat config.js
